import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:provider/provider.dart';import '../models/publisher.dart';import '../state/reference_list_notifiers.dart';import '../validators/validators.dart';import '../widgets/entity_form_scaffold.dart';
class PublisherFormScreen extends StatefulWidget{final int? id;const PublisherFormScreen({super.key,this.id});@override State<PublisherFormScreen>createState()=>_S();}class _S extends State<PublisherFormScreen>{final key=GlobalKey<FormState>();final name=TextEditingController(),country=TextEditingController();Publisher? old;bool loading=true,dirty=false,saving=false;@override void initState(){super.initState();_load();}Future<void>_load()async{if(widget.id!=null){old=await context.read<PublisherListNotifier>().findById(widget.id!);if(old!=null){name.text=old!.name;country.text=old!.country;}}if(mounted)setState(()=>loading=false);}@override void dispose(){name.dispose();country.dispose();super.dispose();}Future<void>leave()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Есть несохранённые изменения'),content:const Text('Выйти без сохранения?'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Остаться')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Выйти'))]))??false;if(ok&&mounted){setState(()=>dirty=false);context.pop();}}Future<void>save()async{if(!key.currentState!.validate())return;setState(()=>saving=true);final v=Publisher(id:old?.id??0,name:name.text.trim(),country:country.text.trim(),deletedAt:old?.deletedAt);widget.id==null?await context.read<PublisherListNotifier>().create(v):await context.read<PublisherListNotifier>().update(v);if(mounted){setState(()=>dirty=false);context.go('/publishers');}}@override Widget build(BuildContext c){if(loading)return const Scaffold(body:Center(child:CircularProgressIndicator()));return EntityFormScaffold(title:widget.id==null?'Новое издательство':'Редактирование издательства',dirty:dirty,saving:saving,onSave:save,onLeaveRequested:leave,child:Form(key:key,onChanged:()=>setState(()=>dirty=true),child:Column(children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'Название'),validator:(v)=>textLength(v,min:2,max:100)),const SizedBox(height:12),TextFormField(controller:country,decoration:const InputDecoration(labelText:'Страна'),validator:(v)=>textLength(v,min:2,max:60))])));}}
